package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class QuantityRatioEquivalenceTest {
 @Test public void allConditionsUsePublicPartWholeAndMatchBothRepresentations(){Set<String> seen=new HashSet<>();assertEquals(450,QuantityRatioEquivalence.domainSize());for(int i=0;i<450;i++){Question q=QuantityRatioEquivalence.at(i);assertTrue(seen.add(q.signature()));var v=QuantityRatioEquivalence.read(q);assertNotNull(v);BigDecimal rate=BigDecimal.valueOf(v.part()).divide(BigDecimal.valueOf(v.total()));assertTrue(new Checker().check(q,List.of(),List.of(rate.toPlainString(),rate.movePointRight(2).toPlainString())).correct());assertFalse(new Checker().check(q,List.of(),List.of(rate.add(BigDecimal.ONE).toPlainString(),rate.movePointRight(2).toPlainString())).correct());assertEquals(1,new Checker().check(q,List.of(),List.of(rate.toPlainString(),rate.movePointRight(2).add(BigDecimal.ONE).toPlainString())).index);q.expression="poison";q.answers=new String[]{"999","999"};HelpPlan h=HelpPlan.forQuestion(q);assertEquals(4,h.size());assertFalse(h.canTransfer());List<String> values=List.of(""+v.total(),""+v.part(),rate.toPlainString(),rate.movePointRight(2).toPlainString());for(int j=0;j<4;j++){assertTrue(h.step(j).accepts(values.get(j)));assertEquals("",h.step(j).after);}}
 }
 @Test public void gradeSixReusesNotationAndForwardRelationsButAddsReverseContext(){var pack=GlobalCurriculum.packs("GB").stream().filter(x->x.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();for(String id:List.of(QuantityRatioEquivalence.ID,FractionPercentEquivalence.ID,PercentageNotation.FRACTION,PercentageNotation.DECIMAL,DecimalPercentReverse.ID,EquivalentQuantityStories.FRACTION,EquivalentQuantityStories.DECIMAL,EquivalentQuantityStories.PERCENT))assertTrue(id,pack.inGrade(id,6));Learning.Profile profile=new Learning.Profile();profile.countryCode="KR";profile.educationSystem="kr-national";assertTrue(GlobalCurriculum.available(profile).stream().noneMatch(s->QuantityRatioEquivalence.supports(s.id)));}
 @Test public void unseenSupplyAndWrongRestorationAreIndependentOfHiddenAnswers(){Generator g=new Generator(new Random(96));List<String> recent=new ArrayList<>();for(int i=0;i<150;i++){Question q=g.next(QuantityRatioEquivalence.ID,recent,false,GlobalCurriculum.limits("england-primary-2021-v1",QuantityRatioEquivalence.ID,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());}Question q=QuantityRatioEquivalence.make(40,1,"L");HelpPlan h=HelpPlan.forQuestion(q);HelpPlan.Draft draft=new HelpPlan.Draft();draft.questionId=q.id;draft.teachingVersion=q.studyGuide.teachingVersion;draft.entries=new ArrayList<>(List.of("40","1","0.026"));draft.stage=2;assertEquals(2,h.restore(draft,q.id).stage);assertFalse(h.step(2).accepts("0.026"));assertTrue(h.step(2).accepts("0.025"));}
}
